from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class TrafficSelectors(SchemaObject):
    local_ip_adress = SchemaField(name="localIpAdress")
    local_ip_prefix_length = SchemaField(name="localIpPrefixLength")
    remote_ip_address = SchemaField(name="remoteIpAddress")
    remote_ip_prefix_length = SchemaField(name="remoteIpPrefixLength")
    local_ip_port = SchemaField(name="localIpPort")
    remote_ip_port = SchemaField(name="remoteIpPort")
    protocol = SchemaField(name="protocol")

    def __init__(self, local_ip_adress, local_ip_prefix_length, remote_ip_address, remote_ip_prefix_length,
                 local_ip_port, remote_ip_port, protocol):
        self.local_ip_adress = local_ip_adress
        self.local_ip_prefix_length = local_ip_prefix_length
        self.remote_ip_address = remote_ip_address
        self.remote_ip_prefix_length = remote_ip_prefix_length
        self.local_ip_port = local_ip_port
        self.remote_ip_port = remote_ip_port
        self.protocol = protocol
        super(TrafficSelectors, self).__init__()


class IkeAssociations(SchemaObject):
    policy_order_number = SchemaField(name="policyOrderNumber")
    ike_sa_req_id = SchemaField(name="ikeSaReqId")
    local_tunnel_end_point = SchemaField(name="localTunnelEndPoint")
    status = SchemaField(name="status")
    mode = SchemaField(name="mode")

    def __init__(self, policy_order_number, ike_sa_req_id, local_tunnel_end_point, status, mode):
        self.policy_order_number = policy_order_number
        self.ike_sa_req_id = ike_sa_req_id
        self.local_tunnel_end_point = local_tunnel_end_point
        self.status = status
        self.mode = mode
        super(IkeAssociations, self).__init__()


class AssociationsInfos(SchemaObject):
    policy_order_number = SchemaField(name="policyOrderNumber")
    ipsec_sa_req_id = SchemaField(name="ipsecSaReqId")
    peer_state = SchemaField(name="peerState")
    inbound_spi = SchemaField(name="inboundSPI")
    outbound_spi = SchemaField(name="outboundSPI")
    traffic_selectors = SchemaField(name="trafficSelectors", klass=TrafficSelectors, many=True)

    def __init__(self, policy_order_number, ipsec_sa_req_id, peer_state, inbound_spi, outbound_spi, traffic_selectors):
        self.policy_order_number = policy_order_number
        self.ipsec_sa_req_id = ipsec_sa_req_id
        self.peer_state = peer_state
        self.inbound_spi = inbound_spi
        self.outbound_spi = outbound_spi
        self.traffic_selectors = traffic_selectors
        super(AssociationsInfos, self).__init__()


class IPSecurityAssociation(SchemaObject):
    ike_associations = SchemaField(name="ikeAssociations", klass=IkeAssociations, many=True)
    associations_infos = SchemaField(name="associationsInfos", klass=AssociationsInfos, many=True)

    def __init__(self, ike_associations, associations_infos):
        self.ike_associations = ike_associations
        self.associations_infos = associations_infos
        super(IPSecurityAssociation, self).__init__()
